        internal static Js pickLocale(Js loc)
        {
            return ((loc && Locales.own(SadeSati.LABELS, loc)) ? loc : Js.S("en"));
        }

        internal static Js label(Js loc, Js key)
        {
            Js m = ((SadeSati.LABELS.Get(SadeSati.pickLocale(loc)).NonNullish ?? SadeSati.LABELS.Get("en")).NonNullish ?? Js.Obj());
            Js en = (SadeSati.LABELS.Get("en").NonNullish ?? Js.Obj());
            return ((Locales.own(m, key).NonNullish ?? Locales.own(en, key)).NonNullish ?? Js.S(""));
        }

        internal static Js statusLabel(Js loc, Js status)
        {
            Js s = (status.NonNullish ?? Js.S(""));
            Js m = SadeSati.STATUS_LABELS.Get(SadeSati.pickLocale(loc));
            return (Locales.own(m, s).NonNullish ?? s);
        }

        internal static Js remediesList(Js loc)
        {
            return ((SadeSati.REMEDIES.Get(SadeSati.pickLocale(loc)).NonNullish ?? SadeSati.REMEDIES.Get("en")).NonNullish ?? Js.Arr());
        }

        internal static Js fmt1(Js n)
        {
            return (Js.StrictEquals(Js.TypeOf(n), Js.S("number")) ? n : Js.N(0d)).ToFixed(Js.N(1d));
        }

        internal static Js durationLabel(Js loc, Js years)
        {
            Js y = SadeSati.fmt1(years);
            switch (SadeSati.pickLocale(loc).CaseKey())
            {
                case "hi":
                return Js.Cat("लगभग ", y.Str(), " वर्ष");
                case "mr":
                return Js.Cat("सुमारे ", y.Str(), " वर्षे");
                case "te":
                return Js.Cat("సుమారు ", y.Str(), " సంవత్సరాలు");
                case "ta":
                return Js.Cat("சுமார் ", y.Str(), " ஆண்டுகள்");
                case "kn":
                return Js.Cat("ಸುಮಾರು ", y.Str(), " ವರ್ಷಗಳು");
                case "ml":
                return Js.Cat("ഏകദേശം ", y.Str(), " വർഷം");
                case "gu":
                return Js.Cat("આશરે ", y.Str(), " વર્ષ");
                case "bn":
                return Js.Cat("প্রায় ", y.Str(), " বছর");
                case "pa":
                return Js.Cat("ਲਗਭਗ ", y.Str(), " ਸਾਲ");
                default:
                return Js.Cat("approx ", y.Str(), " years");
            }
            return Js.Undefined;
        }

        internal static Js statusDescription(Js loc, Js st)
        {
            Js moon = (st.Get("moon_sign").NonNullish ?? Js.S(""));
            Js saturn = (st.Get("saturn_sign").NonNullish ?? Js.S(""));
            Js status = (st.Get("status").NonNullish ?? Js.S(""));
            switch (SadeSati.pickLocale(loc).CaseKey())
            {
                case "hi":
                switch (status.CaseKey())
                {
                    case "rising":
                    return Js.Cat("शनि वर्तमान में आपकी चंद्र राशि (", moon.Str(), ") से पूर्व राशि में संक्रमण कर रहे हैं — साढ़े साती का प्रारंभिक चरण।");
