                    case "peak":
                    return Js.Cat("शनी सध्या आपल्या चंद्र राशी (", moon.Str(), ") वरच गोचर करत आहेत — साडेसातीचा शिखर टप्पा.");
                    case "setting":
                    return Js.Cat("शनी सध्या आपल्या चंद्र राशी (", moon.Str(), ") पासून पुढील राशीत आहेत — साडेसातीचा अंतिम टप्पा.");
                }
                return Js.Cat("सध्या आपण साडेसाती मुक्त आहात. शनी (", saturn.Str(), ") आपल्या चंद्र राशीपासून (", moon.Str(), ") दूर आहेत.");
                case "te":
                switch (status.CaseKey())
