        internal static readonly Js EXTRA_CSS = Js.S("\n.cover .moon-sign-badge {\n  display: inline-block;\n  margin-top: 8mm;\n  padding: 3mm 8mm;\n  background: var(--brand-primary);\n  color: #fff;\n  font-size: 14pt;\n  border-radius: 2mm;\n}\n.status-card {\n  margin: 4mm 0;\n  padding: 5mm;\n  border-radius: 2mm;\n  border-left: 4px solid;\n}\n.status-card.peak    { background: #fef2f2; border-left-color: #dc2626; }\n.status-card.rising  { background: #fff7ed; border-left-color: #ea580c; }\n.status-card.setting { background: #fefce8; border-left-color: #ca8a04; }\n.status-card.clear   { background: #f0fdf4; border-left-color: #16a34a; }\n.status-card .label {\n  text-transform: uppercase;\n  font-size: 9pt;\n  letter-spacing: 0.5pt;\n  color: var(--brand-secondary);\n  margin-bottom: 1mm;\n}\n.status-card .value { font-size: 18pt; font-weight: 700; margin-bottom: 2mm; }\n.status-card .detail { font-size: 10pt; }\ntr.current-window td { background: #fff7ed; font-weight: 600; }\n.remedies {\n  margin-top: 6mm;\n  padding: 5mm;\n  background: #fafafa;\n  border-left: 3px solid var(--brand-secondary);\n}\n.remedies ul { margin: 2mm 0 0 6mm; padding: 0; }\n.empty-list { margin: 3mm 0; color: var(--brand-secondary); font-style: italic; }\n");

        internal static Js windowRow(Js loc, Js w)
        {
            return Js.Cat("<tr>\n  <td>", Shared.esc(w.Get("StartDate")).Str(), "</td>\n  <td>", Shared.esc(w.Get("EndDate")).Str(), "</td>\n  <td>", Shared.esc(SadeSati.durationLabel(loc, w.Get("DurationYears"))).Str(), "</td>\n  <td>", Shared.esc(Shared.listText(w.Get("SignsTraversed"))).Str(), "</td>\n</tr>");
        }

        internal static Js windowsTable(Js loc, Js rows, Js emptyKey)
        {
            if (((!Js.IsArray(rows)) || Js.StrictEquals(rows.Get("length"), Js.N(0d))))
            {
                return Js.Cat("<p class=\"empty-list\">", Shared.esc(SadeSati.label(loc, emptyKey)).Str(), "</p>");
            }
            return Js.Cat("<table>\n  <thead>\n    <tr>\n      <th>", Shared.esc(SadeSati.label(loc, Js.S("from"))).Str(), "</th>\n      <th>", Shared.esc(SadeSati.label(loc, Js.S("to"))).Str(), "</th>\n      <th>", Shared.esc(SadeSati.label(loc, Js.S("duration"))).Str(), "</th>\n      <th>", Shared.esc(SadeSati.label(loc, Js.S("signs_traversed"))).Str(), "</th>\n    </tr>\n  </thead>\n  <tbody>\n    ", rows.Map(Js.Fn(args1_ =>
            {
                Js w = Js.Arg(args1_, 0);
                return SadeSati.windowRow(loc, w);
            })).Join(Js.S("\n    ")).Str(), "\n  </tbody>\n</table>");
        }

        internal static Js formatGenerated(Js iso)
        {
            if ((!iso))
            {
                return Js.S("");
            }
            Js d = Shared.parseTimestamp(iso);
            if (Js.IsNaN(d.GetTime()))
            {
                return iso;
            }
            Js p = Js.Fn(args1_ =>
            {
                Js n = Js.Arg(args1_, 0);
                return Js.ToStringValue(n).PadStart(Js.N(2d), Js.S("0"));
            });
            return Js.Cat(d.GetUtcFullYear().Str(), "-", p.Call(Js.Add(d.GetUtcMonth(), Js.N(1d))).Str(), "-", p.Call(d.GetUtcDate()).Str(), " ", p.Call(d.GetUtcHours()).Str(), ":", p.Call(d.GetUtcMinutes()).Str(), " UTC");
        }

        internal static Js renderSadeSatiHtml(Js data, Js branding)
        {
            data = Shared.withoutNullItems(Js.Obj(
                Js.Spread(data),
                Js.Prop("Locale", Shared.safeLocale(data.Get("Locale")))), Js.Undefined);
            Js loc = (data.Get("Locale").NonNullish ?? Js.S(""));
            Js b = Shared.resolveBranding(data.Get("Branding"), branding);
            Js subject = (data.Get("Subject").NonNullish ?? Js.Obj());
            Js status = (data.Get("CurrentStatus").NonNullish ?? Js.Obj());
            Js title = SadeSati.label(loc, Js.S("title_sade"));
            Js cover = Js.Cat("<section class=\"cover\">\n  ", Shared.coverBrandingHtml(b).Str(), "\n  <h1>", Shared.esc(title).Str(), "</h1>\n  <div class=\"subject\">", Shared.esc(subject.Get("name")).Str(), "</div>\n  <div class=\"meta\">\n    ", Shared.esc(SadeSati.label(loc, Js.S("born"))).Str(), " ", Shared.esc(subject.Get("birth_date")).Str(), " ", Shared.esc(SadeSati.label(loc, Js.S("at"))).Str(), " ", Shared.esc(subject.Get("birth_time")).Str(), "<br>\n    ", Shared.esc(subject.Get("birth_place")).Str(), "\n  </div>\n  <div class=\"moon-sign-badge\">\n    ", Shared.esc(SadeSati.label(loc, Js.S("moon_sign"))).Str(), ": ", Shared.esc(subject.Get("moon_sign")).Str(), "\n  </div>\n  <div class=\"generated\">\n    ", Shared.esc(SadeSati.label(loc, Js.S("generated"))).Str(), " ", Shared.esc(SadeSati.formatGenerated(data.Get("GeneratedAt"))).Str(), "\n  </div>\n</section>");
            Js statusCls = (status.Get("status").NonNullish ?? Js.S(""));
            Js currentCard = Js.Cat("<h2>", Shared.esc(SadeSati.label(loc, Js.S("section_current"))).Str(), "</h2>\n<div class=\"status-card ", Shared.esc(statusCls).Str(), "\">\n  <div class=\"label\">", Shared.esc(SadeSati.label(loc, Js.S("current_phase"))).Str(), "</div>\n  <div class=\"value\">", Shared.esc(SadeSati.statusLabel(loc, status.Get("status"))).Str(), "</div>\n  <div class=\"detail\">", Shared.esc(SadeSati.statusDescription(loc, status)).Str(), "</div>\n</div>");
            Js pastSection = Js.Cat("<h2>", Shared.esc(SadeSati.label(loc, Js.S("section_past"))).Str(), "</h2>\n", SadeSati.windowsTable(loc, data.Get("Past"), Js.S("no_past")).Str());
            Js activeSection = Js.S("");
            Js cur = data.Get("Current");
            if (cur)
            {
                activeSection = Js.Cat("<h2>", Shared.esc(SadeSati.label(loc, Js.S("section_active_window"))).Str(), "</h2>\n<table>\n  <tbody>\n    <tr class=\"current-window\"><td>", Shared.esc(SadeSati.label(loc, Js.S("from"))).Str(), "</td><td>", Shared.esc(cur.Get("StartDate")).Str(), "</td></tr>\n    <tr class=\"current-window\"><td>", Shared.esc(SadeSati.label(loc, Js.S("to"))).Str(), "</td><td>", Shared.esc(cur.Get("EndDate")).Str(), "</td></tr>\n    <tr class=\"current-window\"><td>", Shared.esc(SadeSati.label(loc, Js.S("signs_traversed"))).Str(), "</td><td>", Shared.esc(Shared.listText(cur.Get("SignsTraversed"))).Str(), "</td></tr>\n  </tbody>\n</table>");
            }
            Js futureSection = Js.Cat("<h2>", Shared.esc(SadeSati.label(loc, Js.S("section_future"))).Str(), "</h2>\n", SadeSati.windowsTable(loc, data.Get("Future"), Js.S("no_future")).Str());
            Js remediesSection = Js.Cat("<h2>", Shared.esc(SadeSati.label(loc, Js.S("section_remedies"))).Str(), "</h2>\n<div class=\"remedies\">\n  <p>", Shared.esc(SadeSati.label(loc, Js.S("remedies_intro"))).Str(), "</p>\n  <ul>\n    ", SadeSati.remediesList(loc).Map(Js.Fn(args1_ =>
            {
                Js r = Js.Arg(args1_, 0);
                return Js.Cat("<li>", Shared.esc(r).Str(), "</li>");
            })).Join(Js.S("\n    ")).Str(), "\n  </ul>\n</div>");
            Js bodyHtml = Js.Arr(cover, currentCard, pastSection, activeSection, futureSection, remediesSection).Filter(Js.Fn(args1_ =>
            {
                Js s = Js.Arg(args1_, 0);
                return Js.StrictNotEquals(s, Js.S(""));
            })).Join(Js.S("\n\n"));
            return Shared.layoutDocument(Js.Obj(
                Js.Prop("lang", (loc || Js.S("en"))),
                Js.Prop("title", title),
                Js.Prop("branding", b),
                Js.Prop("bodyHtml", bodyHtml),
                Js.Prop("extraCss", SadeSati.EXTRA_CSS)));
        }
    }
